 const finance=await createFinanceAsset(f.reviewer,financeAssetSchema.parse({assetNumber:key(),name:'Packaging line motor',accountId:fixed,depreciationAccountId:accumulated,depreciationExpenseAccountId:f.accounts.expense,currency:'THB',cost:'2500',residual:'0',usefulLifeMonths:60,inServiceDate:'2026-01-02'}),key());
 await activateAsset(f.manager,String(finance.id),{expectedVersion:1,periodId:f.period,entryDate:'2026-01-02',offsetAccountId:f.accounts.payable,evidenceRef:'Approved equipment acquisition'},key());
 return seedAsset(actor,{branchId:f.branch,departmentId:f.department,code:key(),name:'Packaging line motor',category:'Production equipment',currency:'THB',costMinor:250000,acquiredDate:'2026-01-02',warrantyEnd:'2027-01-02',financeAssetId:String(finance.id),financeAssetVersion:2});
