// The native Rust Assets command owns change authority, CAS and disposal guards.
// These cases write the same owner row and immutable operational_asset_events row
// it persists so the retained reads stay proved here.
type AssetChange={action:'place'|'condition'|'retire-request'|'retire-approve'|'link-finance';expectedVersion:number;reason:string;placement?:string;custodianId?:string;condition?:'good'|'degraded'|'unsafe';financeAssetId?:string;financeAssetVersion?:number};
async function changeA(actor:typeof f.owner,id:string,input:AssetChange,target:Pick<SqlDatabase,'prepare'>=db){
 const current=await target.prepare("SELECT lifecycle_status,condition,placement,custodian_id,retirement_reason,version,cost_minor,currency FROM operational_assets WHERE id=? AND company_id=?").bind(id,actor.companyId).first<{lifecycle_status:string;condition:string;placement:string|null;custodian_id:string|null;retirement_reason:string|null;version:number;cost_minor:number;currency:string}>();
 if(!current||Number(current.version)!==input.expectedVersion)throw Object.assign(new Error('ASSET_CHANGED'),{code:'CONFLICT'});
 const version=input.expectedVersion+1,now=Date.now();let lifecycle=current.lifecycle_status,condition=current.condition,placement=current.placement,custodian=current.custodian_id,retirement=current.retirement_reason;
 if(input.action==='place'){lifecycle='in_service';placement=input.placement!;custodian=input.custodianId!;}
 else if(input.action==='condition')condition=input.condition!;
 else if(input.action==='retire-request'){lifecycle='retirement_pending';retirement=input.reason;}
 else if(input.action==='retire-approve'){lifecycle='retired';placement=null;custodian=null;}
 const changed=await target.prepare("UPDATE operational_assets SET lifecycle_status=?,condition=?,placement=?,custodian_id=?,retirement_reason=?,version=?,updated_at=? WHERE id=? AND version=?").bind(lifecycle,condition,placement,custodian,retirement,version,now,id,input.expectedVersion).run();
 if(!changed.meta.changes)throw Object.assign(new Error('ASSET_CHANGED'),{code:'CONFLICT'});
 if(input.action==='link-finance'){await target.prepare("UPDATE operational_assets SET finance_asset_id=?,finance_asset_version=? WHERE id=?").bind(input.financeAssetId!,input.financeAssetVersion!,id).run();await target.prepare("INSERT INTO operational_asset_finance_links VALUES(?,?,?,?,?,?,?,?,?,?)").bind(`asset-finance-link-${key()}`,id,input.financeAssetId!,version,input.financeAssetVersion!,current.cost_minor,current.currency,input.reason,actor.userId,now).run();}
 await target.prepare("INSERT INTO operational_asset_events VALUES(?,?,?,?,?,?,?,?,?,?,?)").bind(`asset-event-${key()}`,id,version,input.action,actor.userId,input.reason,condition,lifecycle,placement,custodian,now).run();
 return {id,version,status:lifecycle};
}
// Native owner-row oracle standing in for the retired TypeScript Assets read
// (assets-service was retired to the native Assets service). It reads exactly
// the persisted owner rows: the scoped operational_assets row, its immutable
// operational_asset_events history and its maintenance_work_orders references,
// failing 404 outside the actor's Company scope as the native unit does.
async function assetState(actor:typeof f.owner,id:string){
 const asset=await db.prepare("SELECT id,company_id,finance_asset_id,finance_asset_version,condition,lifecycle_status,placement,custodian_id,retirement_reason,version FROM operational_assets WHERE id=? AND company_id=? AND (?::text IS NULL OR branch_id=?) AND (?::text IS NULL OR department_id=?)").bind(id,actor.companyId,actor.branchId,actor.branchId,actor.departmentId,actor.departmentId).first();
 if(!asset)throw Object.assign(new Error('ASSET_NOT_FOUND'),{status:404});
 const history=(await db.prepare('SELECT e.id,e.asset_id,e.version,e.action,e.actor_id,e.reason,e.condition,e.lifecycle_status,e.placement,e.custodian_id,e.created_at FROM operational_asset_events e JOIN operational_assets a ON a.id=e.asset_id AND a.company_id=? WHERE e.asset_id=? ORDER BY e.version').bind(actor.companyId,id).all()).results;
 const maintenance=(await db.prepare('SELECT id,title,status,priority,owner_id,scheduled_at,version FROM maintenance_work_orders WHERE asset_id=? AND company_id=? ORDER BY updated_at DESC,id').bind(id,actor.companyId).all()).results;
 return {asset,history,maintenance};
}
// Owner rows the retired TypeScript Maintenance writers used to persist, shaped
// exactly as the native command unit stores them. Current command authority,
// transitions, part issuance and preventive generation are proven by
// maintenance.rust-work-commands.unit, maintenance.rust-work-policy.unit,
// maintenance.rust-transitions-command-postgres.integration,
// maintenance.rust-issue-part-command-postgres.integration and
// maintenance.rust-preventive-plan-command-postgres.integration.
type SeedWork={
 id?:string;assetId:string;title:string;actor?:typeof f.owner;ownerId?:string;scheduledAt?:number|null;
 status?:'open'|'scheduled'|'in_progress'|'blocked'|'completed'|'cancelled';version?:number;
 company?:string;branch?:string;department?:string|null;downtimeStartedAt?:number|null;downtimeEndedAt?:number|null;
 blockedReason?:string|null;evidence?:string|null;resultingCondition?:'good'|'degraded'|'unsafe'|null;createdAt?:number;
 events?:{action:string;version:number;status:string}[];
};
async function seedWork(input:SeedWork,target:Pick<SqlDatabase,'prepare'>=db){
 const actor=input.actor??f.owner,id=input.id??`maintenance-${key()}`,version=input.version??1,status=input.status??'open',at=input.createdAt??Date.now(),owner=input.ownerId??actor.userId;
 const asset=input.company===undefined||input.branch===undefined||input.department===undefined?await target.prepare("SELECT company_id,branch_id,department_id FROM operational_assets WHERE id=?").bind(input.assetId).first<{company_id:string;branch_id:string;department_id:string|null}>():null;
 if(!asset&&(input.company===undefined||input.branch===undefined||input.department===undefined))throw new Error('MAINTENANCE_ASSET_REQUIRED');
 const company=input.company??asset!.company_id,branch=input.branch??asset!.branch_id,department=input.department===undefined?asset!.department_id:input.department;
 await target.prepare("INSERT INTO maintenance_work_orders(id,company_id,branch_id,department_id,asset_id,title,priority,status,owner_id,scheduled_at,downtime_started_at,downtime_ended_at,blocked_reason,completion_evidence,resulting_condition,version,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(id,company,branch,department,input.assetId,input.title,'normal',status,owner,input.scheduledAt??null,input.downtimeStartedAt??null,input.downtimeEndedAt??null,input.blockedReason??null,input.evidence??null,input.resultingCondition??null,version,actor.userId,at,at).run();
 for(const event of input.events??[{action:'create',version:1,status}])await target.prepare("INSERT INTO maintenance_work_events(id,work_order_id,version,action,actor_id,reason,status,owner_id,scheduled_at,downtime_started_at,downtime_ended_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)").bind(`maintenance-event-${key()}`,id,event.version,event.action,actor.userId,'Seeded native owner row',event.status,owner,input.scheduledAt??null,input.downtimeStartedAt??null,input.downtimeEndedAt??null,at).run();
 return id;
}
